# Writes .github/workflows/scan-sites-1.yml and scan-sites-2.yml: "run workflow" forms with one checkbox per site.
# GitHub allows 25 inputs per form, sites.json has 24+ sites, so the sites are split over two forms.
# Run again after you add a site to sites.json:  python scripts/gen_scan_forms.py   (tests/scan_selftest.py checks they are in sync)
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PER_FORM = 12            # 12 site boxes + 4 type boxes + types_list + measure + fresh = 19 inputs (limit 25)

TEMPLATE = """name: {title}
# GENERATED by scripts/gen_scan_forms.py - edit sites.json and run the script instead of editing by hand.
# Tick the sites you want; everything else is the same as in "scan". Ticking no site is an error (it would not mean "all").
on:
  workflow_dispatch:
    inputs:
{inputs}
      t_pdf:
        description: "Types: PDF"
        type: boolean
        default: false
      t_audio:
        description: "Types: audio (mp3, m4a, wav, ogg, aac)"
        type: boolean
        default: false
      t_video:
        description: "Types: video (mp4, webm, mov)"
        type: boolean
        default: false
      t_docs:
        description: "Types: documents (doc, docx, rtf, ppt, pptx, xls, xlsx, epub)"
        type: boolean
        default: false
      types_list:
        description: "More types (added to the ticked ones): comma list of extensions, e.g. zip,srt. No type ticked and this empty = every type"
        default: ""
      measure:
        description: "Check file sizes (slower)"
        type: boolean
        default: true
      fresh:
        description: "Ignore saved progress (tick this after changing file types)"
        type: boolean
        default: false
permissions: {{contents: write}}
jobs:
  pick:
    runs-on: ubuntu-24.04
    outputs:
      sites: ${{{{ steps.p.outputs.sites }}}}
    steps:
      - id: p
        env:
          FORM: ${{{{ toJSON(inputs) }}}}
        run: |
          python3 - <<'PY' >> "$GITHUB_OUTPUT"
          import json, os, sys
          form = json.loads(os.environ["FORM"])
          picked = [k[2:] for k, v in form.items() if k.startswith("s_") and v in (True, "true")]
          if not picked:
              print("::error::Tick at least one site.", file=sys.stderr)
              sys.exit(1)
          print("sites=" + ",".join(picked))
          PY
  scan:
    needs: pick
    uses: ./.github/workflows/scan.yml
    with:
      sites: ${{{{ needs.pick.outputs.sites }}}}
      t_pdf: ${{{{ inputs.t_pdf }}}}
      t_audio: ${{{{ inputs.t_audio }}}}
      t_video: ${{{{ inputs.t_video }}}}
      t_docs: ${{{{ inputs.t_docs }}}}
      types_list: ${{{{ inputs.types_list }}}}
      measure: ${{{{ inputs.measure }}}}
      fresh: ${{{{ inputs.fresh }}}}
    secrets: inherit
"""


def main() -> None:
    sites = json.loads((ROOT / "sites.json").read_text("utf-8"))["sites"]
    parts = [sites[i:i + PER_FORM] for i in range(0, len(sites), PER_FORM)]
    assert len(parts) <= 2, "more than 24 sites: add a third form (and a name for it)"
    for n, part in enumerate(parts, 1):
        inputs = "\n".join(
            f'      s_{s["id"]}:\n        description: "{s["name"]} ({s["id"]})"\n        type: boolean\n        default: false'
            for s in part)
        title = f"scan - sites {n} ({part[0]['id']} ... {part[-1]['id']})"
        (ROOT / ".github/workflows" / f"scan-sites-{n}.yml").write_text(
            TEMPLATE.format(title=title, inputs=inputs), encoding="utf-8")
        print(f"scan-sites-{n}.yml: {len(part)} sites")


if __name__ == "__main__":
    main()
